Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_0RB1LA_1RC0LA_1LB1RD_1LB1RB : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_0RB1LA_1RC0LA_1LB1RD_1LB1RB. Qed.

