(** 0RB1LA_1RC0LA_1RD1RB_1LB1LA *)
Definition tm_0RB1LA_1RC0LA_1RD1RB_1LB1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB
  | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S0 DL StA
  | StC, S0 => mk S1 DR StD
  | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DL StB
  | StD, S1 => mk S1 DL StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB1LA_1RC0LA_1RD1RB_1LB1LA : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_0RB1LA_1RC0LA_1RD1RB_1LB1LA pins_0RB1LA_1RC0LA_1RD1RB_1LB1LA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB1LA_1RC0LA_1RD1RB_1LB1LA : Fam := mkFam 2 [[S1;S1];[S0;S1]] [] [[S1;S0;S1];[S1];[];[S0;S0;S1]] Binary 1 [mkFill 0 [] 0 [] 3;mkFill 0 [] 0 [] 2;mkFill 0 [] 0 [] 0;mkFill 1 [] 0 [] 1] StA S0 false [].
Local Notation FAM := fam_0RB1LA_1RC0LA_1RD1RB_1LB1LA.

(** ** The ladder, as DATA

    5 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1LA_1RC0LA_1RD1RB_1LB1LA : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_0RB1LA_1RC0LA_1RD1RB_1LB1LA.

Definition rules_0RB1LA_1RC0LA_1RD1RB_1LB1LA : list LRule := map fst lad.
Local Notation rules := rules_0RB1LA_1RC0LA_1RD1RB_1LB1LA.

Lemma ladder_ok_0RB1LA_1RC0LA_1RD1RB_1LB1LA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LA_1RC0LA_1RD1RB_1LB1LA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LA_1RC0LA_1RD1RB_1LB1LA. Qed.

