  match r, ph with
  | 1, 0 => farm1_0_0RB1LA_1RC1RD_1LD1RB_0LC0LA
  | 1, 1 => farm1_1_0RB1LA_1RC1RD_1LD1RB_0LC0LA
  | 1, 2 => farm1_2_0RB1LA_1RC1RD_1LD1RB_0LC0LA
