Lemma bootl_1RB1LB_1LC1LD_0LA1RC_1LB0RC :
  stepn tm 5 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
