Theorem nqhtr_1RB1LB_1LC1LD_0LA1RC_1LB0RC : NeverQuasiHaltsTr tm_1RB1LB_1LC1LD_0LA1RC_1LB0RC.
Proof.
  eapply (boardN_neverqhtr tm_1RB1LB_1LC1LD_0LA1RC_1LB0RC pins_1RB1LB_1LC1LD_0LA1RC_1LB0RC FAM 1
                           iarm_1RB1LB_1LC1LD_0LA1RC_1LB0RC 0 1
                           farm_1RB1LB_1LC1LD_0LA1RC_1LB0RC 1 1
                           fm1_1RB1LB_1LC1LD_0LA1RC_1LB0RC fm2_1RB1LB_1LC1LD_0LA1RC_1LB0RC 0
                           nrules vsegs_1RB1LB_1LC1LD_0LA1RC_1LB0RC vis_1RB1LB_1LC1LD_0LA1RC_1LB0RC
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
