  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_rhs_1RB1LC_1LA0RC_1LB0RD_0LC1RD : forall d r,
  d < fm_b FAM - 1 -> r < 1 + 1 ->
  lr_rhs (iarm_1RB1LC_1LA0RC_1LB0RD_0LC1RD d r)
    = cls_conf FAM (cls_side FAM [] 0 r (astride 1 1 r) [S d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
