Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1RD_0LC1LC_0RD1LB_1RA0RC : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1RD_0LC1LC_0RD1LB_1RA0RC. Qed.

