Lemma bootl_1RB1RD_1LC1RA_0RD0LC_0RB1LA :
  stepn tm 36 InitES = Some (lift (fam_cfg FAM ([0;0], 0, 0))).
Proof.
  assert (H : match csteps tm 36 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0;0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 36 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1RD_1LC1RA_0RD0LC_0RB1LA : NeverQuasiHaltsTr tm_1RB1RD_1LC1RA_0RD0LC_0RB1LA.
Proof.
  eapply (boardN_neverqhtr tm_1RB1RD_1LC1RA_0RD0LC_0RB1LA pins_1RB1RD_1LC1RA_0RD0LC_0RB1LA FAM 1
                           iarm_1RB1RD_1LC1RA_0RD0LC_0RB1LA 0 1
                           farm_1RB1RD_1LC1RA_0RD0LC_0RB1LA 1 1
                           fm1_1RB1RD_1LC1RA_0RD0LC_0RB1LA fm2_1RB1RD_1LC1RA_0RD0LC_0RB1LA 0
                           nrules vsegs_1RB1RD_1LC1RA_0RD0LC_0RB1LA vis_1RB1RD_1LC1RA_0RD0LC_0RB1LA
                           [0;0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
